8. {'MESH:C535858': {'cui': 'MESH:C535858', 'name': 'HEM dysplasia', 'types': 'Disease', 'aliases': 'Chondrodystrophy, Hydropic And Prenatally Lethal Type|Greenberg dysplasia|Greenberg Skeletal Dysplasia|Hem Skeletal Dysplasia|Hydrops - Ectopic Calcification - Moth-Eaten Skeletal Dysplasia|Hydrops-Ectopic Calcification-Moth-Eaten Skeletal Dysplasia|Moth-Eaten Skeletal Dysplasia', 'definition': ''}}
9. {'MESH:D014842': {'cui': 'MESH:D014842', 'name': 'von Willebrand Diseases', 'types': 'Disease', 'aliases': "Angiohemophilia|Angiohemophilias|Disorder, Von Willebrand|Hemophilia, Vascular|Pseudohemophilias, Vascular|Pseudohemophilia, Vascular|Vascular Hemophilia|Vascular Hemophilias|Vascular Pseudohemophilia|Vascular Pseudohemophilias|von Willebrand Disease|von Willebrand Disease, Recessive Form|Von Willebrand Disorder|von Willebrand's Disease|von Willebrand's Diseases|Von Willebrand's Factor Deficiency", 'definition': 'Group of hemorrhagic disorders in which the VON WILLEBRAND FACTOR is either quantitatively or qualitatively abnormal. They are usually inherited as an autosomal dominant trait though rare kindreds are autosomal recessive. Symptoms vary depending on severity and disease type but may include prolonged bleeding time, deficiency of factor VIII, and impaired platelet adhesion.'}
10. {'MESH:D009767': {'cui': 'MESH:D009767', 'name': 'Obesity, Morbid', 'types': 'Disease', 'aliases': 'Morbid Obesities|Morbid Obesity|Obesities, Morbid|Obesities, Severe|Obesity, Severe|Severe Obesities|Severe Obesity', 'definition': 'The condition of weighing two, three, or more times the ideal weight, so called because it is associated with many serious and life-threatening disorders. In the BODY MASS INDEX, morbid obesity is defined as having a BMI greater than 40.0 kg/m2.'}
11. {'MESH:D038901': {'cui': 'MESH:D038901', 'name': 'Mental Retardation, X-Linked', 'types': 'Disease', 'aliases': 'Mental Retardation, X Linked|Retardation, X-Linked Mental|X Linked Mental Retardation|X-Linked Mental Retardation|X Linked Mental Retardation Disorders|X-Linked Mental Retardation Disorders|X-Linked Mental Retardations|X Linked Mental Retardation Syndromes|X-Linked Mental Retardation Syndromes', 'definition': 'A class of genetic disorders resulting in INTELLECTUAL DISABILITY that is associated either with mutations of GENES located on the X CHROMOSOME or aberrations in the structure of the X chromosome (SEX CHROMOSOME ABERRATIONS).'}}
