13. {'MESH:D005313': {'cui': 'MESH:D005313', 'name': 'Fetal Death', 'types': 'Disease', 'aliases': 'Death, Fetal|Deaths, Fetal|Demise, Fetal|Fetal Deaths|Fetal Demise|Fetal Mummification|Mummification, Fetal', 'definition': 'Death of the developing young in utero. BIRTH of a dead FETUS is STILLBIRTH.'}
14. {'MESH:D056729': {'cui': 'MESH:D056729', 'name': 'von Willebrand Disease, Type 3', 'types': 'Disease', 'aliases': "Type 3 Von Willebrand's Disease|Type 3 VWD|Von Willebrand Disease, Severe Form|VON WILLEBRAND DISEASE, TYPE III|VWD3|VWD, TYPE 3", 'definition': 'A subtype of von Willebrand disease that results from a total or near total deficiency of VON WILLEBRAND FACTOR.'}
15. {'MESH:D057215': {'cui': 'MESH:D057215', 'name': 'Body Dysmorphic Disorders', 'types': 'Disease', 'aliases': 'Body Dysmorphic Disorder|Body Image Disfunction|Body Image Disfunctions|Body Image Disorder|Body Image Disorders|Disfunction, Body Image|Disfunctions, Body Image|Disorder, Body Dysmorphic|Disorders, Body Dysmorphic|Disorders, Body Image|Dysmorphic Disorder, Body|Dysmorphic Disorders, Body|Image Disfunction, Body|Image Disfunctions, Body|Image Disorders, Body', 'definition': 'Preoccupations with appearance or self-image causing significant distress or impairment in important areas of functioning.'}
16. {'OMIM:616188': {'cui': 'OMIM:616188', 'name': 'RETINAL DYSTROPHY AND OBESITY', 'types': 'Disease', 'aliases': 'RDOB', 'definition': ''}}
17. {'MESH:D056128': {'cui': 'MESH:D056128', 'name': 'Obesity, Abdominal', 'types': 'Disease', 'aliases': 'Abdominal Obesities|Abdominal Obesity|Central Obesities|Central Obesity|Obesities, Abdominal|Obesities, Central|Obesities, Visceral|Obesity, Central|Obesity, Visceral|Visceral Obesities|Visceral Obesity', 'definition': 'A condition of having excess fat in the abdomen. Abdominal obesity is typically defined as waist circumferences of 40 inches or more in men and 35 inches or more in women. Abdominal obesity raises the risk of developing disorders, such as DIABETES; HYPERTENSION; and METABOLIC SYNDROME.'}
18. {'MESH:D003865': {'cui': 'MESH:D003865', 'name': 'Depressive Disorder, Major', 'types': 'Disease', 'aliases': 'Depression, Involutional|Depressive Disorders, Major|Involutional Depression|Involutional Melancholia|Involutional Paraphrenia|Involutional Paraphrenias|Involutional Psychoses|Involutional Psychosis|Major Depressive Disorder|Major Depressive Disorders|MDD|Melancholia, Involutional|Paraphrenia, Involutional|Paraphrenias, Involutional|Psychoses, Involutional|Psychosis, Involutional|SAD, INCLUDED|UNIPOLAR DEPRESSION SEASONAL AFFECTIVE DISORDER, INCLUDED', 'definition': 'Disorder in which five (or more) of the following symptoms have been present during the same 2-week period and represent a change from previous functioning; at least one of the symptoms is either (1) depressed mood or (2) loss of interest or pleasure. Symptoms include: depressed mood most of the day, nearly every daily; markedly diminished interest or pleasure in activities most of the day, nearly every day; significant weight loss when not dieting or weight gain; Insomnia or hypersomnia nearly every day; psychomotor agitation or retardation nearly every day; fatigue or loss of energy nearly every day; feelings of worthlessness or excessive or inappropriate guilt; diminished ability to think or concentrate, or indecisiveness, nearly every day; or  recurrent thoughts of death, recurrent suicidal ideation without a specific plan, or a suicide attempt. (DSM-5)'}
